package org.apache.commons.lang.text;

import java.io.*;
import java.io.Reader;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ArrayUtils;
import org.apache.commons.lang.SystemUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StrBuilder.appendFixedWidthPadRight
 */
public class StrBuilder_appendFixedWidthPadRight_TriageGen2Test {

    @Test
    public void testAppendFixedWidthPadRight_WidthZero() {
        StrBuilder sb = new StrBuilder("initial");
        sb.appendFixedWidthPadRight("test", 0, ' ');
        assertEquals("initial", sb.toString());
        assertEquals(7, sb.length());
    }

    @Test
    public void testAppendFixedWidthPadRight_WidthNegative() {
        StrBuilder sb = new StrBuilder("initial");
        sb.appendFixedWidthPadRight("test", -5, ' ');
        assertEquals("initial", sb.toString());
        assertEquals(7, sb.length());
    }

    @Test
    public void testAppendFixedWidthPadRight_ObjNull_WithPadding() {
        StrBuilder sb = new StrBuilder();
        String nullText = "NULL";
        sb.setNullText(nullText);
        // nullText length is 4, width is 6, padChar is '.'
        // Expected: "NULL.."
        sb.appendFixedWidthPadRight(null, 6, '.');
        assertEquals("NULL..", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_ObjNull_NoPaddingNeeded() {
        StrBuilder sb = new StrBuilder();
        sb.setNullText("NULL");
        // nullText length is 4, width is 2
        // Expected: "NU" (based on str.getChars(0, strLen, buffer, size) logic where strLen is 4, but width is 2)
        // Note: The implementation uses strLen for getChars but increases size by width.
        // If strLen (4) >= width (2), it copies 4 chars but size only increases by 2. 
        // This reveals a potential bug in the source code provided, but we test the current logic.
        sb.appendFixedWidthPadRight(null, 2, '.');
        assertEquals("NULL", sb.toString()); 
        // Based on code: strLen=4, width=2. strLen >= width is true.
        // str.getChars(0, 4, buffer, 0) copies "NULL". size becomes 0 + 2 = 2.
        // However, toString() usually relies on size.
        assertEquals(2, sb.length());
    }

    @Test
    public void testAppendFixedWidthPadRight_StringShorterThanWidth() {
        StrBuilder sb = new StrBuilder("Start: ");
        // "abc" len 3, width 6, pad '*' -> "abc***"
        sb.appendFixedWidthPadRight("abc", 6, '*');
        assertEquals("Start: abc***", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_StringLongerThanWidth() {
        StrBuilder sb = new StrBuilder("Start: ");
        // "abcdef" len 6, width 3, pad '*' -> "abcdef"
        // Implementation: if strLen >= width, str.getChars(0, strLen, buffer, size)
        // size += width.
        sb.appendFixedWidthPadRight("abcdef", 3, '*');
        assertEquals("Start: abcdef", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_StringEqualsWidth() {
        StrBuilder sb = new StrBuilder();
        // "test" len 4, width 4, pad '#' -> "test"
        sb.appendFixedWidthPadRight("test", 4, '#');
        assertEquals("test", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_IntegerObject() {
        StrBuilder sb = new StrBuilder();
        // 123 len 3, width 5, pad '0' -> "12300"
        sb.appendFixedWidthPadRight(123, 5, '0');
        assertEquals("12300", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_Chaining() {
        StrBuilder sb = new StrBuilder();
        sb.appendFixedWidthPadRight("A", 3, '-')
          .appendFixedWidthPadRight("B", 3, '-');
        assertEquals("A--B--", sb.toString());
    }
}
